47	
48	```dart
49	Map<String, String> _savedMessageEntryIds = {};
50	
51	Future<void> _ensureLocalCacheLoaded() {
52	  return _localCacheLoad ??= () async {
53	    _cachedSessions = await _localCache.readSessions();
