1	import 'package:cerne/core/network/failure.dart';
2	import 'package:cerne/features/entries/data/entries_local_cache.dart';
3	import 'package:cerne/features/entries/data/entries_remote_data_source.dart';
4	import 'package:cerne/features/entries/domain/entities/entries_page.dart';
5	import 'package:cerne/features/entries/domain/entities/entry.dart';
6	import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
7	import 'package:cerne/features/session/domain/repositories/session_repository.dart';
8	import 'package:fpdart/fpdart.dart';
9	
10	/// Wraps [EntriesRemoteDataSource] and owns [cachedEntries] — an in-memory
11	/// mirror, backed by [EntriesLocalCache], of every entry this process has
12	/// seen (via a successful [create]/[list]/[search]), so it survives an app
13	/// restart. Registered as a `get_it` `lazySingleton` so the cache survives
14	/// across modal opens (same lifetime pattern as RF03's `VaultRepository`).
15	/// Read back out for display by `RecordsBloc` when a fetch fails outright —
16	/// the on-device fallback the PRD's "local read cache" describes
17	/// (requirements.md line 50/125).
18	class EntriesRepositoryImpl implements EntriesRepository {
19	  EntriesRepositoryImpl(
20	    this._remoteDataSource, {
21	    required this._sessionRepository,
22	    required this._localCache,
23	  });
24	
25	  final EntriesRemoteDataSource _remoteDataSource;
26	  final SessionRepository _sessionRepository;
27	  final EntriesLocalCache _localCache;
28	
29	  final List<Entry> _cachedEntries = [];
30	  Future<void>? _localCacheLoad;
31	
32	  // Runs once per process; every public method awaits it before touching
33	  // `_cachedEntries`, so the persisted cache is always merged in before
34	  // either a remote call resolves or `cachedEntries` is read back out —
35	  // closing the race between "app just launched" and "first read of the
36	  // cache."
37	  Future<void> _ensureLocalCacheLoaded() {
38	    return _localCacheLoad ??= _localCache.readAll().then(_mergeEntries);
39	  }
40	
41	  void _mergeEntries(List<Entry> fetched) {
42	    for (final entry in fetched) {
43	      final index = _cachedEntries.indexWhere((e) => e.id == entry.id);
44	      if (index >= 0) {
45	        _cachedEntries[index] = entry;
46	      } else {
47	        _cachedEntries.add(entry);
48	      }
49	    }
50	  }
51	
52	  Future<void> _cacheAndPersist(List<Entry> fetched) async {
53	    _mergeEntries(fetched);
54	    await _localCache.writeAll(_cachedEntries);
55	  }
56	
57	  @override
58	  Future<Either<Failure, Entry>> create({
59	    required String content,
60	    required EntrySource source,
61	  }) async {
