8	/// The shared seam `ChatBloc`/`ChatSessionsBloc` depend on (data-model.md,
9	/// contracts/chat-repository.md). Registered as a `get_it` `lazySingleton`
10	/// so [cachedSessions]/[cachedMessages] survive across screen rebuilds.
11	abstract class ChatRepository {
12	  /// `POST /chat/sessions` (`chat-sessions-create`). Retries exactly once
13	  /// through `SessionRepository.refresh()` on `AuthExpiredFailure` (same
14	  /// shape as every other non-streaming call in this codebase).
15	  Future<Either<Failure, ChatSession>> createSession({required String title});
16	
17	  /// `GET /chat/sessions` (`chat-sessions-list`), ordered by
18	  /// `lastUserMessageAt` desc (FR-008).
19	  Future<Either<Failure, ChatSessionsPage>> listSessions({
20	    String? cursor,
21	    int? limit,
22	  });
23	
24	  /// Every session returned by any successful [listSessions] call this
25	  /// process has made, backed by `ChatLocalCache` so it survives a restart
26	  /// (research.md R4) — the offline fallback `ChatSessionsBloc` reads when a
27	  /// fetch fails outright.
28	  List<ChatSession> get cachedSessions;
29	
30	  /// `GET /chat/sessions/:id/messages` (`chat-messages-list`), ordered by
31	  /// `seq`.
32	  Future<Either<Failure, List<ChatMessage>>> listMessages(String sessionId);
33	
34	  /// The last successfully-fetched message list for [sessionId], or `null`
35	  /// if this session's history has never been fetched while online
36	  /// (research.md R4/Clarification 3) — `null` is the signal `ChatBloc` uses
37	  /// to show the "standard no-connection state" instead of any content when
38	  /// selecting it while offline.
39	  List<ChatMessage>? cachedMessages(String sessionId);
40	
41	  /// Persists which conversation to resume on next app open
42	  /// (spec.md Assumptions).
43	  Future<void> setLastActiveSessionId(String? sessionId);
44	  Future<String?> get lastActiveSessionId;
45	
46	  /// `POST /chat/sessions/:id/messages` (`chat-messages-send`), SSE. Retries
47	  /// the whole call exactly once via `SessionRepository.refresh()` only if
48	  /// the very first emitted item is `AuthExpiredFailure` (research.md R3).
49	  Stream<Either<Failure, ChatStreamEvent>> sendMessage({
50	    required String sessionId,
51	    required String content,
52	  });
53	
54	  /// `POST /chat/sessions/:id/messages/:userMessageId/retry`
55	  /// (`chat-messages-retry`), SSE. Same retry-once-if-first-frame-fails
56	  /// shape as [sendMessage] (research.md R3).
57	  Stream<Either<Failure, ChatStreamEvent>> retryMessage({
58	    required String sessionId,
59	    required String userMessageId,
60	  });
61	}
