51	    bool clearSessionId = false,
52	    List<ChatMessage>? messages,
53	    bool? isOffline,
54	    bool? awaitingResponse,
55	    Object? loadFailure = _unset,
56	  }) {
57	    return ChatReady(
58	      sessionId: clearSessionId ? null : (sessionId ?? this.sessionId),
59	      messages: messages ?? this.messages,
60	      isOffline: isOffline ?? this.isOffline,
61	      awaitingResponse: awaitingResponse ?? this.awaitingResponse,
62	      loadFailure: identical(loadFailure, _unset)
63	          ? this.loadFailure
