14	/// The Home/Chat screen's own live conversation — streaming, retry, lazy
15	/// session creation, composer gating (contracts/chat-bloc.md). Depends only
16	/// on `ChatRepository` + `ConnectivityChecker` — never `ChatSessionsBloc`
17	/// nor `SessionBloc` (research.md R7).
18	class ChatBloc extends Bloc<ChatEvent, ChatState> {
19	  ChatBloc({
20	    required ChatRepository chatRepository,
21	    required ConnectivityChecker connectivityChecker,
22	  }) : _chatRepository = chatRepository, // ignore: prefer_initializing_formals
23	       _connectivityChecker = connectivityChecker, // ignore: prefer_initializing_formals
24	       super(const ChatLoading()) {
25	    on<ChatStarted>(_onStarted);
26	    on<ConversationSelected>(_onConversationSelected);
27	    on<NewConversationRequested>(_onNewConversationRequested);
28	    on<MessageSubmitted>(_onMessageSubmitted);
29	    on<MessageRetryRequested>(_onMessageRetryRequested);
30	    on<ChatConnectivityChanged>(_onConnectivityChanged);
31	    _connectivitySubscription = connectivityChecker.onConnectivityChanged.listen(
32	      (isOnline) => add(ChatConnectivityChanged(isOnline)),
33	    );
34	  }
35	
36	  final ChatRepository _chatRepository;
37	  final ConnectivityChecker _connectivityChecker;
38	  late final StreamSubscription<bool> _connectivitySubscription;
39	  final _reauthController = StreamController<void>.broadcast();
40	
41	  /// Guards against a resolved/superseded turn's late emit (defensive,
42	  /// research.md R9) — bumped on every new turn and on every conversation
43	  /// switch/new-conversation request.
44	  int _turnGeneration = 0;
45	
46	  /// A one-shot side effect, not a state (research.md R3/R7) —
47	  /// `HomeChatShellPage` listens to this to raise the "Sessão expirada"
48	  /// overlay.
49	  Stream<void> get reauthRequired => _reauthController.stream;
50	
51	  Future<void> _onStarted(ChatStarted event, Emitter<ChatState> emit) async {
52	    final isOnline = await _connectivityChecker.hasConnection();
53	    final lastId = await _chatRepository.lastActiveSessionId;
54	    if (lastId == null) {
55	      emit(
56	        ChatReady(
57	          sessionId: null,
58	          messages: const [],
59	          isOffline: !isOnline,
60	          awaitingResponse: false,
61	        ),
62	      );
63	      return;
64	    }
65	    await _loadSession(lastId, emit, isOffline: !isOnline);
66	  }
67	
68	  Future<void> _onConversationSelected(
69	    ConversationSelected event,
70	    Emitter<ChatState> emit,
71	  ) async {
72	    _turnGeneration++;
73	    final isOnline = await _connectivityChecker.hasConnection();
74	    await _loadSession(event.sessionId, emit, isOffline: !isOnline);
75	  }
76	
77	  Future<void> _onNewConversationRequested(
78	    NewConversationRequested event,
79	    Emitter<ChatState> emit,
80	  ) async {
81	    _turnGeneration++;
82	    final current = state;
83	    final isOffline = current is ChatReady ? current.isOffline : false;
84	    await _chatRepository.setLastActiveSessionId(null);
85	    emit(
86	      ChatReady(
87	        sessionId: null,
88	        messages: const [],
89	        isOffline: isOffline,
90	        awaitingResponse: false,
91	      ),
92	    );
93	  }
94	
95	  void _onConnectivityChanged(
96	    ChatConnectivityChanged event,
97	    Emitter<ChatState> emit,
98	  ) {
99	    final current = state;
100	    if (current is! ChatReady) return;
101	    emit(current.copyWith(isOffline: !event.isOnline));
102	  }
103	
104	  /// The shared fetch-with-cache-fallback path (Clarification 3).
105	  Future<void> _loadSession(
106	    String sessionId,
107	    Emitter<ChatState> emit, {
108	    required bool isOffline,
109	  }) async {
110	    final result = await _chatRepository.listMessages(sessionId);
111	    await result.match(
112	      (failure) async {
113	        if (failure is AuthExpiredFailure) _reauthController.add(null);
114	        final cached = _chatRepository.cachedMessages(sessionId);
115	        if (cached == null) {
116	          // Never opened while online — the "standard no-connection state"
117	          // instead of any content (Edge Cases).
118	          emit(
119	            ChatReady(
120	              sessionId: sessionId,
121	              messages: const [],
122	              isOffline: isOffline,
123	              awaitingResponse: false,
124	              loadFailure: failure,
125	            ),
126	          );
127	        } else {
128	          emit(
129	            ChatReady(
130	              sessionId: sessionId,
131	              messages: cached,
132	              isOffline: isOffline,
133	              awaitingResponse: false,
134	            ),
135	          );
136	        }
137	      },
138	      (messages) async {
139	        await _chatRepository.setLastActiveSessionId(sessionId);
140	        emit(
141	          ChatReady(
142	            sessionId: sessionId,
143	            messages: messages,
144	            isOffline: isOffline,
145	            awaitingResponse: false,
146	          ),
147	        );
148	      },
149	    );
150	  }
151	
152	  Future<void> _onMessageSubmitted(
153	    MessageSubmitted event,
154	    Emitter<ChatState> emit,
155	  ) async {
156	    final current = state;
157	    if (current is! ChatReady || !current.canSend) return;
158	
159	    if (!await _connectivityChecker.hasConnection()) {
160	      // FR-012 — blocked client-side, never attempted. The composer's own
161	      // isOffline flag (R8's live stream) reflects this on its own shortly.
162	      return;
163	    }
164	
165	    final generation = ++_turnGeneration;
166	    final now = DateTime.now();
167	    final optimisticUser = ChatMessage(
168	      id: 'local-${now.microsecondsSinceEpoch}',
169	      sessionId: current.sessionId ?? '',
170	      role: ChatRole.user,
171	      content: event.text,
172	      seq: current.messages.length,
173	      status: ChatMessageStatus.complete,
174	      retryCount: 0,
175	      createdAt: now,
176	    );
177	    final optimisticAssistant = ChatMessage(
178	      id: 'local-${now.microsecondsSinceEpoch}-response',
179	      sessionId: current.sessionId ?? '',
180	      role: ChatRole.assistant,
181	      content: '',
182	      seq: current.messages.length + 1,
183	      status: ChatMessageStatus.streaming,
184	      retryCount: 0,
185	      createdAt: now,
186	    );
187	    emit(
188	      current.copyWith(
189	        messages: [...current.messages, optimisticUser, optimisticAssistant],
190	        awaitingResponse: true,
191	      ),
192	    );
193	
194	    String sessionId;
195	    if (current.sessionId == null) {
196	      final created = await _chatRepository.createSession(
197	        title: ChatTitleDeriver.derive(event.text),
198	      );
199	      if (generation != _turnGeneration) return;
200	      final maybeId = created.match((_) => null, (s) => s.id);
201	      if (maybeId == null) {
202	        final failure = created.getLeft().toNullable()!;
203	        _failTurn(emit, optimisticAssistant.id, failure);
204	        return;
205	      }
206	      sessionId = maybeId;
207	      await _chatRepository.setLastActiveSessionId(sessionId);
208	    } else {
209	      sessionId = current.sessionId!;
210	    }
211	
212	    final stream = _chatRepository.sendMessage(
213	      sessionId: sessionId,
214	      content: event.text,
215	    );
216	    await _consumeTurn(
217	      stream,
218	      emit,
219	      generation: generation,
220	      sessionId: sessionId,
221	      optimisticUserId: optimisticUser.id,
222	      optimisticAssistantId: optimisticAssistant.id,
223	    );
224	  }
225	
226	  Future<void> _onMessageRetryRequested(
227	    MessageRetryRequested event,
228	    Emitter<ChatState> emit,
229	  ) async {
230	    final current = state;
231	    if (current is! ChatReady || current.awaitingResponse) {
232	      return;
233	    }
234	    final index = current.messages.indexWhere(
235	      (m) =>
236	          m.role == ChatRole.assistant &&
237	          m.status == ChatMessageStatus.failed &&
238	          _userMessageIdFor(current.messages, m) == event.userMessageId,
239	    );
240	    if (index == -1) return;
241	    if (!await _connectivityChecker.hasConnection()) return; // FR-012
242	
243	    final userMessage = current.messages[index - 1];
244	    if (userMessage.isOptimistic) {
245	      // The turn's very first `createSession` call failed (FR-006) — there
246	      // is no persisted session/message yet for `retryMessage` to target, so
247	      // re-run the same lazy-creation path `_onMessageSubmitted` takes.
248	      await _retryLazySessionCreation(current, index, userMessage, emit);
249	      return;
250	    }
251	    if (current.sessionId == null) return;
252	
253	    final generation = ++_turnGeneration;
254	    final now = DateTime.now();
255	    final placeholder = ChatMessage(
256	      id: 'local-${now.microsecondsSinceEpoch}-retry',
257	      sessionId: current.sessionId!,
258	      role: ChatRole.assistant,
259	      content: '',
260	      seq: current.messages[index].seq,
261	      status: ChatMessageStatus.streaming,
262	      retryCount: current.messages[index].retryCount + 1,
263	      createdAt: now,
264	    );
265	    final updatedMessages = [...current.messages];
266	    updatedMessages[index] = placeholder;
267	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
268	
269	    final stream = _chatRepository.retryMessage(
270	      sessionId: current.sessionId!,
271	      userMessageId: event.userMessageId,
272	    );
273	    await _consumeTurn(
274	      stream,
275	      emit,
276	      generation: generation,
277	      sessionId: current.sessionId!,
278	      optimisticUserId: null,
279	      optimisticAssistantId: placeholder.id,
280	    );
281	  }
282	
283	  /// Retries a turn whose lazy `createSession` call (FR-010) itself failed
284	  /// before any session ever existed — reuses `createSession` +
285	  /// `sendMessage` with the original user message's own content, exactly as
286	  /// `_onMessageSubmitted` does for a brand-new conversation.
287	  Future<void> _retryLazySessionCreation(
288	    ChatReady current,
289	    int index,
290	    ChatMessage userMessage,
291	    Emitter<ChatState> emit,
292	  ) async {
293	    final generation = ++_turnGeneration;
294	    final now = DateTime.now();
295	    final placeholder = ChatMessage(
296	      id: 'local-${now.microsecondsSinceEpoch}-retry',
297	      sessionId: userMessage.sessionId,
298	      role: ChatRole.assistant,
299	      content: '',
300	      seq: current.messages[index].seq,
301	      status: ChatMessageStatus.streaming,
302	      retryCount: current.messages[index].retryCount + 1,
303	      createdAt: now,
304	    );
305	    final updatedMessages = [...current.messages];
306	    updatedMessages[index] = placeholder;
307	    emit(current.copyWith(messages: updatedMessages, awaitingResponse: true));
308	
309	    final created = await _chatRepository.createSession(
310	      title: ChatTitleDeriver.derive(userMessage.content),
311	    );
312	    if (generation != _turnGeneration) return;
313	    final maybeId = created.match((_) => null, (s) => s.id);
314	    if (maybeId == null) {
315	      final failure = created.getLeft().toNullable()!;
316	      _failTurn(emit, placeholder.id, failure);
317	      return;
318	    }
319	    await _chatRepository.setLastActiveSessionId(maybeId);
320	
321	    final latest = state;
322	    if (latest is! ChatReady || generation != _turnGeneration) return;
323	    emit(latest.copyWith(sessionId: maybeId));
324	
325	    final stream = _chatRepository.sendMessage(
326	      sessionId: maybeId,
327	      content: userMessage.content,
328	    );
329	    await _consumeTurn(
330	      stream,
331	      emit,
332	      generation: generation,
333	      sessionId: maybeId,
334	      optimisticUserId: userMessage.id,
335	      optimisticAssistantId: placeholder.id,
336	    );
337	  }
338	
339	  /// Shared `emit.forEach`-driven stream consumption for both a fresh send
340	  /// and a retry.
341	  Future<void> _consumeTurn(
342	    Stream<Either<Failure, ChatStreamEvent>> stream,
343	    Emitter<ChatState> emit, {
344	    required int generation,
345	    required String sessionId,
346	    required String? optimisticUserId,
347	    required String optimisticAssistantId,
348	  }) async {
349	    var assistantId = optimisticAssistantId;
350	    await emit.forEach<Either<Failure, ChatStreamEvent>>(
351	      stream,
352	      onData: (result) {
353	        final latest = state;
354	        if (generation != _turnGeneration || latest is! ChatReady) {
355	          return latest;
356	        }
357	        return result.match((failure) {
358	          if (failure is AuthExpiredFailure) _reauthController.add(null);
359	          return _applyFailure(latest, assistantId, failure);
360	        }, (event) => switch (event) {
361	          MessageCreated() => () {
362	            assistantId = event.assistantMessageId;
363	            return _reconcileIds(
364	              latest,
365	              optimisticUserId,
366	              event.userMessageId,
367	              optimisticAssistantId,
368	              event.assistantMessageId,
369	            );
370	          }(),
371	          ContextReceived() => latest,
372	          TokenReceived(delta: final d) => _appendToken(latest, assistantId, d),
373	          StreamDone(assistantMessageId: final id) =>
374	            _completeMessage(latest, id).copyWith(awaitingResponse: false),
375	        });
376	      },
377	    );
378	    await _reconcileSilentFailure(emit, sessionId, assistantId, generation);
379	  }
380	
381	  /// A failure yielded as (or before) the stream's very first item leaves the
382	  /// bubble `failed` with empty content even though the backend may have
383	  /// kept generating in the background and already persisted the full
384	  /// answer by the time the stream closed (e.g. a transient network drop
385	  /// right after `message_created`, before any token arrives). One
386	  /// best-effort refetch here closes that gap without needing the user to
387	  /// leave and come back. Only acts on an empty-content failure — a failure
388	  /// after partial tokens (FR-005) is left exactly as the stream reported
389	  /// it. Note this is a best-effort recovery for a genuinely slow backend,
390	  /// not a substitute for parsing the stream correctly in the first place —
391	  /// it loses the race whenever the backend is still generating (slow/live
392	  /// answers can take several seconds longer than this one refetch waits
393	  /// for).
394	  Future<void> _reconcileSilentFailure(
395	    Emitter<ChatState> emit,
396	    String sessionId,
397	    String assistantId,
398	    int generation,
399	  ) async {
400	    final seeded = state;
401	    if (seeded is! ChatReady || generation != _turnGeneration) return;
402	    final index = seeded.messages.indexWhere((m) => m.id == assistantId);
403	    if (index == -1) return;
404	    final message = seeded.messages[index];
405	    if (message.status != ChatMessageStatus.failed || message.content.isNotEmpty) {
406	      return;
407	    }
408	
409	    final result = await _chatRepository.listMessages(sessionId);
410	    if (generation != _turnGeneration) return;
411	    result.match((_) {}, (serverMessages) {
412	      ChatMessage? persisted;
413	      for (final m in serverMessages) {
414	        if (m.role == ChatRole.assistant && m.seq == message.seq) {
415	          persisted = m;
416	          break;
417	        }
418	      }
419	      final resolved = persisted;
420	      if (resolved == null ||
421	          resolved.status != ChatMessageStatus.complete ||
422	          resolved.content.isEmpty) {
423	        return;
424	      }
425	      final latest = state;
426	      if (latest is! ChatReady || generation != _turnGeneration) return;
427	      final updated = [
428	        for (final m in latest.messages) if (m.id == assistantId) resolved else m,
429	      ];
430	      emit(latest.copyWith(messages: updated));
431	    });
432	  }
433	
434	  void _failTurn(
435	    Emitter<ChatState> emit,
436	    String assistantId,
437	    Failure failure,
438	  ) {
439	    final latest = state;
440	    if (latest is! ChatReady) return;
441	    emit(_applyFailure(latest, assistantId, failure));
442	  }
443	
444	  /// `null` for a retry's `userMessageId` — a retry never targets an
445	  /// optimistic question, only an already-persisted one.
446	  ChatReady _reconcileIds(
447	    ChatReady current,
448	    String? optimisticUserId,
449	    String realUserId,
450	    String optimisticAssistantId,
451	    String realAssistantId,
452	  ) {
453	    final updated = [
454	      for (final m in current.messages)
455	        if (optimisticUserId != null && m.id == optimisticUserId)
456	          _withId(m, realUserId)
457	        else if (m.id == optimisticAssistantId)
458	          _withId(m, realAssistantId)
459	        else
460	          m,
461	    ];
462	    return current.copyWith(messages: updated);
463	  }
464	
465	  ChatMessage _withId(ChatMessage message, String id) => ChatMessage(
466	    id: id,
467	    sessionId: message.sessionId,
468	    role: message.role,
469	    content: message.content,
470	    seq: message.seq,
471	    status: message.status,
472	    retryCount: message.retryCount,
473	    createdAt: message.createdAt,
474	  );
475	
476	  ChatReady _appendToken(ChatReady current, String assistantId, String delta) {
477	    final updated = [
478	      for (final m in current.messages)
479	        if (m.id == assistantId) _withContent(m, m.content + delta) else m,
480	    ];
481	    return current.copyWith(messages: updated);
482	  }
483	
484	  // The backend's `done` SSE event carries no authoritative `content`
485	  // (contracts/zod/chat.ts's `sseDoneEventSchema` has only
486	  // `assistantMessageId`/`finishReason`) — the message's own content, built
487	  // up from this turn's `TokenReceived` deltas, is already the full answer.
488	  ChatReady _completeMessage(ChatReady current, String assistantId) {
489	    final updated = [
490	      for (final m in current.messages)
491	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.complete) else m,
492	    ];
493	    return current.copyWith(messages: updated);
494	  }
495	
496	  /// Keeps whatever partial `content` had already accumulated — never
497	  /// removed, hidden, or blanked (FR-005).
498	  ChatReady _applyFailure(
499	    ChatReady current,
500	    String assistantId,
501	    Failure failure,
502	  ) {
503	    final updated = [
504	      for (final m in current.messages)
505	        if (m.id == assistantId) _withStatus(m, ChatMessageStatus.failed) else m,
506	    ];
507	    return current.copyWith(messages: updated, awaitingResponse: false);
508	  }
509	
510	  ChatMessage _withContent(ChatMessage message, String content) => ChatMessage(
511	    id: message.id,
512	    sessionId: message.sessionId,
513	    role: message.role,
514	    content: content,
515	    seq: message.seq,
516	    status: message.status,
517	    retryCount: message.retryCount,
518	    createdAt: message.createdAt,
519	  );
520	
521	  ChatMessage _withStatus(ChatMessage message, ChatMessageStatus status) =>
522	      ChatMessage(
523	        id: message.id,
524	        sessionId: message.sessionId,
525	        role: message.role,
526	        content: message.content,
527	        seq: message.seq,
528	        status: status,
529	        retryCount: message.retryCount,
530	        createdAt: message.createdAt,
531	      );
532	
533	  /// Position-matching (research.md R10) — the id of the user message
534	  /// immediately preceding [message] in [messages], or `null` if it isn't
535	  /// immediately preceded by one.
536	  String? _userMessageIdFor(List<ChatMessage> messages, ChatMessage message) {
537	    final index = messages.indexWhere((m) => m.id == message.id);
538	    if (index <= 0) return null;
539	    final preceding = messages[index - 1];
540	    return preceding.role == ChatRole.user ? preceding.id : null;
541	  }
542	
543	  @override
544	  Future<void> close() {
545	    unawaited(_connectivitySubscription.cancel());
546	    unawaited(_reauthController.close());
547	    return super.close();
548	  }
549	}
