19	/// Fixed dark-green header (☰ + "Cerne" wordmark) and the live conversation
20	/// area — `ChatBloc`/`ChatSessionsBloc` are provided by `app_router.dart`'s
21	/// `/home` route builder (research.md R7), not here.
22	class HomeChatShellPage extends StatefulWidget {
23	  const HomeChatShellPage({super.key});
24	
25	  @override
26	  State<HomeChatShellPage> createState() => _HomeChatShellPageState();
27	}
