29	class _HomeChatShellPageState extends State<HomeChatShellPage> {
30	  late final StreamSubscription<void> _reauthSubscription;
31	
32	  @override
33	  void initState() {
34	    super.initState();
35	    // The one sanctioned cross-bloc touch point (research.md R3/R7) — lives
36	    // in this widget, never inside `ChatBloc` itself.
37	    _reauthSubscription = context.read<ChatBloc>().reauthRequired.listen((_) {
38	      if (!mounted) return;
39	      context.read<SessionBloc>().add(const AuthExpiredDetected());
40	    });
41	  }
42	
43	  @override
44	  void dispose() {
45	    _reauthSubscription.cancel();
46	    super.dispose();
47	  }
48	
49	  @override
50	  Widget build(BuildContext context) {
51	    return Scaffold(
52	      backgroundColor: DesignTokens.colorSurfaceBg,
53	      drawer: const AppDrawer(),
54	      onDrawerChanged: (isOpen) {
55	        if (isOpen) {
56	          context.read<ChatSessionsBloc>().add(const SessionsRefreshRequested());
57	        }
58	      },
59	      appBar: AppBar(
60	        backgroundColor: DesignTokens.colorPrimary,
61	        foregroundColor: DesignTokens.colorOnPrimary,
62	        title: Text(
63	          'Cerne',
64	          style: DesignTokens.textTitleLg.copyWith(color: DesignTokens.colorOnPrimary),
65	        ),
66	      ),
67	      body: BlocBuilder<ChatBloc, ChatState>(
68	        builder: (context, state) {
69	          final chatReady = state is ChatReady ? state : null;
70	          final List<ChatMessage> messages = chatReady?.messages ?? const [];
71	          final isOffline = chatReady?.isOffline ?? false;
72	          final canSend = chatReady?.canSend ?? false;
73	          final loadFailure = chatReady?.loadFailure;
